package com.huntmaster;

import com.google.gson.JsonObject;
import java.time.Instant;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;

/** Minimal own-account observations, sampled on the client thread. */
final class AccountSnapshot
{
	// Values documented by RuneLite's ACCOUNT_TYPE varbit (gameval IRONMAN).
	private static final String[] ACCOUNT_TYPES = {"NORMAL", "IRONMAN", "ULTIMATE_IRONMAN",
		"HARDCORE_IRONMAN", "GROUP_IRONMAN", "HARDCORE_GROUP_IRONMAN", "UNRANKED_GROUP_IRONMAN"};
	private static final java.util.Map<String, Quest> QUEST_BY_NAME = new java.util.HashMap<>();
	static
	{
		for (Quest quest : Quest.values()) QUEST_BY_NAME.putIfAbsent(quest.getName().toLowerCase(java.util.Locale.ROOT), quest);
	}
    private static final String[] QUESTS = {
        "Desert Treasure II - The Fallen Empire", "Regicide", "Dragon Slayer II", "Secrets of the North",
        "Priest in Peril", "The Heart of Darkness", "Song of the Elves", "The Final Dawn", "Perilous Moons",
        "The Ides of Milk", "Bone Voyage", "The Blood Moon Rises", "Fallen From Grace", "Death Plateau",
        "Horror from the Deep", "Children of the Sun", "A Kingdom Divided", "Troubled Tortugans", "Dragon Slayer I"
    };
    static JsonObject read(Client client)
    {
        JsonObject result = new JsonObject();
        result.addProperty("schemaVersion", 1);
        result.addProperty("rsn", client.getLocalPlayer().getName());
        result.addProperty("observedAt", Instant.now().toString());
        JsonObject quests = new JsonObject();
        for (String name : QUESTS) observeQuest(client, quests, name, false);
        result.add("quests", quests);
        JsonObject miniquests = new JsonObject();
        observeQuest(client, miniquests, "The Frozen Door", false);
        observeQuest(client, miniquests, "Enter the Abyss", false);
        result.add("miniquests", miniquests);
        JsonObject started = new JsonObject();
        observeQuest(client, started, "Fairytale II - Cure a Queen", true);
        result.add("startedQuests", started);
        JsonObject access = new JsonObject();
        observeQuest(client, access, "His Faithful Servants", true);
        if (access.has("His Faithful Servants")) access.add("His Faithful Servants started", access.remove("His Faithful Servants"));
        result.add("access", access);
        JsonObject skills = new JsonObject();
        skills.addProperty("slayer", client.getRealSkillLevel(Skill.SLAYER));
        skills.addProperty("firemaking", client.getRealSkillLevel(Skill.FIREMAKING));
        skills.addProperty("fishing", client.getRealSkillLevel(Skill.FISHING));
        result.add("skills", skills);
        JsonObject account = new JsonObject();
        int accountType = client.getVarbitValue(net.runelite.api.gameval.VarbitID.IRONMAN);
        if (accountType >= 0 && accountType < ACCOUNT_TYPES.length) account.addProperty("type", ACCOUNT_TYPES[accountType]);
        result.add("account", account);
        JsonObject slayer = new JsonObject();
        int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        slayer.addProperty("killsRemaining", remaining);
        if (remaining > 0)
        {
            java.util.List<Integer> rows = client.getDBRowsByValue(net.runelite.api.gameval.DBTableID.SlayerTask.ID,
                net.runelite.api.gameval.DBTableID.SlayerTask.COL_ID, 0, client.getVarpValue(VarPlayerID.SLAYER_TARGET));
            if (rows != null && !rows.isEmpty())
            {
                String name = taskName(client, rows.get(0));
                if ("Bosses".equalsIgnoreCase(name))
                {
                    java.util.List<Integer> bossRows = client.getDBRowsByValue(net.runelite.api.gameval.DBTableID.SlayerTaskSublist.ID,
                        net.runelite.api.gameval.DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0,
                        client.getVarbitValue(net.runelite.api.gameval.VarbitID.SLAYER_TARGET_BOSSID));
                    name = null;
                    if (bossRows != null && !bossRows.isEmpty())
                    {
                        Object[] field = client.getDBTableField(bossRows.get(0), net.runelite.api.gameval.DBTableID.SlayerTaskSublist.COL_TASK, 0);
                        if (field != null && field.length > 0 && field[0] instanceof Integer)
                            name = taskName(client, (Integer) field[0]);
                    }
                }
                if (name != null) slayer.addProperty("task", name);
            }
        }
        result.add("slayer", slayer);
        return result;
    }
    private static String taskName(Client client, int row)
    {
        Object[] field = client.getDBTableField(row, net.runelite.api.gameval.DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
        return field != null && field.length > 0 && field[0] instanceof String ? (String) field[0] : null;
    }

    private static void observeQuest(Client client, JsonObject destination, String name, boolean started)
    {
        Quest quest = QUEST_BY_NAME.get(name.toLowerCase(java.util.Locale.ROOT));
        if (quest == null) return;
        QuestState state = quest.getState(client);
        if (state != null) destination.addProperty(name, started ? state != QuestState.NOT_STARTED : state == QuestState.FINISHED);
    }
}

package com.huntmaster;

import com.google.gson.JsonObject;
import java.util.Objects;
import java.util.UUID;

/** Shared immutable server view. No local progress increments or persisted visibility. */
final class AssignmentDashboardState
{
    static final long INACTIVITY_MS = 20 * 60 * 1000L;
    static final class Assignment
    {
        final String id, boss, classification, overlayText;
        final int progress, required;
        final Long reward;
        final boolean group;
        Assignment(JsonObject task, boolean group)
        { this(task,group,false); }
        Assignment(JsonObject task, boolean group, boolean completion)
        {
            id = UUID.fromString(task.get("id").getAsString()).toString();
            boss = task.get("boss").getAsString();
            if (boss.isBlank() || boss.length() > 128) throw new IllegalArgumentException("Invalid boss");
            progress = number(task, "progress"); required = number(task, "requiredKC");
            if (required < 1 || (!completion && progress > required)) throw new IllegalArgumentException("Invalid progress");
            reward = task.has("rewardPoints") && !task.get("rewardPoints").isJsonNull() ? (long) number(task,"rewardPoints") : null;
            classification = task.has("classification") ? task.get("classification").getAsString() : "";
            if (classification.length() > 40) throw new IllegalArgumentException("Invalid classification");
            this.group = group;
            overlayText = progress+"/"+required+" KC: "+boss;
        }
        private static int number(JsonObject task, String key)
        {
            String value = task.get(key).getAsString();
            if (!value.matches("[0-9]{1,9}")) throw new IllegalArgumentException("Invalid number");
            return Integer.parseInt(value);
        }
    }
    static final class View
    {
        final Assignment assignment, completed;
        final String connection;
        final boolean connected;
        View(Assignment assignment, Assignment completed, String connection, boolean connected)
        { this.assignment=assignment; this.completed=completed; this.connection=connection; this.connected=connected; }
    }
    private volatile View view = new View(null,null,"Log in to RuneScape",false);
    private long sequence, sessionStarted, lastCredit = -1, lastCreditedObservation = -1;
    private String rsn, completionCandidate;
    View view() { return view; }
    synchronized void reset(String account, long now)
    { completionCandidate=null; rsn=account; sequence=0; sessionStarted=now; lastCredit=-1; lastCreditedObservation=-1; view=new View(null,null,account==null?"Log in to RuneScape":"Connecting...",false); }
    synchronized boolean accept(JsonObject response, long now, String creditedAssignment, long observedAt)
    {
        if (rsn == null || !response.get("success").getAsBoolean() || !rsn.equalsIgnoreCase(response.get("rsn").getAsString())) return false;
        long next = response.has("sequence") ? response.get("sequence").getAsLong() : sequence+1;
        if (next < sequence)
        {
            // A newer poll can overtake an acknowledgement. Keep the newer view,
            // but still recognize that this session's own kill was credited.
            recognizeCredit(view.assignment,creditedAssignment,observedAt,now);
            return false;
        }
        String status=response.get("status").getAsString();
        if (!status.equals("solo") && !status.equals("group") && !status.equals("no_assignment")) return false;
        Assignment assignment = response.get("assignment").isJsonNull() ? null : new Assignment(response.getAsJsonObject("assignment"),status.equals("group"));
        if (!Objects.equals(assignment==null?null:assignment.id,view.assignment==null?null:view.assignment.id)) { lastCredit=-1; lastCreditedObservation=-1; }
        recognizeCredit(assignment,creditedAssignment,observedAt,now);
        Assignment completed=assignment==null?view.completed:null;
        if(assignment==null && view.assignment!=null && response.has("completedAssignment") && !response.get("completedAssignment").isJsonNull())
        {
            try {
                Assignment confirmed=new Assignment(response.getAsJsonObject("completedAssignment"),false,true);
                if(confirmed.id.equals(completionCandidate) && confirmed.progress>=confirmed.required && confirmed.reward!=null)completed=confirmed;
            } catch(RuntimeException ignored) { /* Invalid optional metadata must not retain an active overlay. */ }
        }
        completionCandidate=assignment==null?null:assignment.id;
        sequence=next;
        view=new View(assignment,completed,"Connected to Huntmaster",true);
        return true;
    }
    private void recognizeCredit(Assignment assignment,String creditedAssignment,long observedAt,long now)
    {
        if(assignment!=null && assignment.id.equals(creditedAssignment) && observedAt>=sessionStarted
            && observedAt<=now && observedAt>lastCreditedObservation)
        { lastCredit=now; lastCreditedObservation=observedAt; }
    }
    synchronized void connection(String message)
    { if (!view.connection.equals(message)) view=new View(view.assignment,view.completed,message,false); }
    synchronized void clearCompleted()
    { completionCandidate=null; view=new View(view.assignment,null,view.connection,view.connected); }
    synchronized String overlay(long now, boolean enabled)
    {
        Assignment a=view.assignment;
        return enabled && view.connected && a!=null && a.progress<a.required && lastCredit>=0 && now>=lastCredit && now-lastCredit<INACTIVITY_MS
            ? a.overlayText : null;
    }
}

package com.huntmaster;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

final class AssignmentProgressOverlay extends OverlayPanel
{
    private final AssignmentDashboardState state;
    private final BosscapeSettings config;
    private final Client client;
    AssignmentProgressOverlay(HuntmasterPlugin plugin,Client client,AssignmentDashboardState state,BosscapeSettings config)
    { super(plugin);this.client=client;this.state=state;this.config=config;setPosition(OverlayPosition.TOP_LEFT); }
    @Override public Dimension render(Graphics2D graphics)
    {
        if(client.getGameState()!=GameState.LOGGED_IN)return null;
        String text=state.overlay(System.currentTimeMillis(),config.showAssignmentProgressOverlay());
        if(text==null)return null;
        panelComponent.getChildren().add(LineComponent.builder().left(text).build());
        return super.render(graphics);
    }
}

package com.huntmaster;

/** Counter-name aliases reviewed against RuneLite Chat Commands; not NPC aliases. */
final class BossCounterAliases
{
    private BossCounterAliases() { }
    static boolean matches(String assigned, String counterName)
    {
        if (assigned == null || counterName == null) return false;
        if (assigned.equalsIgnoreCase(counterName)) return true;
        switch (assigned.toLowerCase(java.util.Locale.ROOT))
        {
            case "barrows brothers":
                return counterName.equalsIgnoreCase("Barrows chest") || counterName.equalsIgnoreCase("Barrows Chests");
            case "moons of peril":
                return counterName.equalsIgnoreCase("Lunar Chest") || counterName.equalsIgnoreCase("Lunar Chests");
            case "the nightmare":
                return counterName.equalsIgnoreCase("Nightmare");
            case "the hueycoatl":
                return counterName.equalsIgnoreCase("Hueycoatl");
            case "the mimic":
                return counterName.equalsIgnoreCase("Mimic");
            case "the leviathan": return counterName.equalsIgnoreCase("Leviathan");
            case "the whisperer": return counterName.equalsIgnoreCase("Whisperer");
            case "the gauntlet": return counterName.equalsIgnoreCase("Gauntlet");
            case "the corrupted gauntlet": return counterName.equalsIgnoreCase("Corrupted Gauntlet");
            default:
                return false;
        }
    }
}

package com.huntmaster;

final class BossDefinition
{
    private final String name;
    private final boolean evidenceOnly;
    private final String profileKey;

    private final String kcMessagePrefix;

    private final int pendingWindowTicks;

    private final String detectorVersion;

    private final BossDetectorType detectorType;


    // ==================================================
    // DEDICATED TOTAL-COUNT VARP METADATA
    // ==================================================

    /*
     * RuneLite / OSRS varp containing the encounter's
     * dedicated total completion / activity count.
     *
     * Used by:
     * - COMPLETION detectors
     * - ACTIVITY detectors
     *
     * Null for detector types that do not use one.
     */
    private final Integer completionVarpId;




    // ==================================================
    // STANDARD NPC CONSTRUCTOR
    // ==================================================

    public BossDefinition(
            String name,
            String profileKey,
            String kcMessagePrefix,
            int pendingWindowTicks,
            String detectorVersion)
    {
        this(
                name,
                profileKey,
                kcMessagePrefix,
                pendingWindowTicks,
                detectorVersion,
                BossDetectorType.STANDARD_NPC,
                null
        );
    }


    // ==================================================
    // DETECTOR TYPE CONSTRUCTOR
    // ==================================================

    public BossDefinition(
            String name,
            String profileKey,
            String kcMessagePrefix,
            int pendingWindowTicks,
            String detectorVersion,
            BossDetectorType detectorType)
    {
        this(
                name,
                profileKey,
                kcMessagePrefix,
                pendingWindowTicks,
                detectorVersion,
                detectorType,
                null
        );
    }


    // ==================================================
    // FULL CONSTRUCTOR
    // ==================================================

    public BossDefinition(
            String name,
            String profileKey,
            String kcMessagePrefix,
            int pendingWindowTicks,
            String detectorVersion,
            BossDetectorType detectorType,
            Integer completionVarpId)
    {
        this(name, profileKey, kcMessagePrefix, pendingWindowTicks, detectorVersion, detectorType, completionVarpId, false);
    }

    private BossDefinition(String name, String profileKey, String kcMessagePrefix, int pendingWindowTicks, String detectorVersion, BossDetectorType detectorType, Integer completionVarpId, boolean evidenceOnly)
    {
        this.evidenceOnly = evidenceOnly;
        this.name =
                name;

        this.profileKey =
                profileKey;

        this.kcMessagePrefix =
                kcMessagePrefix;

        this.pendingWindowTicks =
                pendingWindowTicks;

        this.detectorVersion =
                detectorVersion;

        this.detectorType =
                detectorType;

        this.completionVarpId =
                completionVarpId;

    }


    // ==================================================
    // GETTERS
    // ==================================================

    public static BossDefinition betaCandidate(String name, String profileKey, String prefix)
    { return new BossDefinition(name, profileKey, prefix, 10, "generic-beta-v1", BossDetectorType.STANDARD_NPC, null, true); }

    static BossDefinition totalCounterCandidate(String name, String profileKey)
    { return new BossDefinition(name, profileKey, "Your " + name, 10,
        DoomCompletionEvidence.BOSS.equals(name) ? DoomCompletionEvidence.DETECTOR_VERSION : "dedicated-total-beta-v1",
        BossDetectorType.COMPLETION, SpecialEncounterTotals.varp(name), true); }

    static BossDefinition dagannothComponent(String component)
    { return new BossDefinition("Dagannoth Kings", "dagannoth_" + component,
        "Your Dagannoth " + component + " kill count is:", 10,
        "dagannoth-" + component + "-beta-v1", BossDetectorType.STANDARD_NPC, null, true); }

    public boolean isEvidenceOnly() { return evidenceOnly; }

    public String getName()
    {
        return name;
    }

    public String getProfileKey()
    {
        return profileKey;
    }

    public String getKcMessagePrefix()
    {
        return kcMessagePrefix;
    }

    public int getPendingWindowTicks()
    {
        return pendingWindowTicks;
    }

    public String getDetectorVersion()
    {
        return detectorVersion;
    }

    public BossDetectorType getDetectorType()
    {
        return detectorType;
    }

    public Integer getCompletionVarpId()
    {
        return completionVarpId;
    }

}

package com.huntmaster;

final class BossDetector
{
    private final BossDefinition definition;



    /*
     * STANDARD_NPC:
     * Previous RuneLite boss KC.
     *
     * COMPLETION:
     * Previous RuneLite completion total.
     */
    private Integer lastKc;


    public BossDetector(
            BossDefinition definition)
    {
        this.definition =
                definition;

        this.lastKc =
                null;
    }


    // ==================================================
    // CORE
    // ==================================================

    public BossDefinition getDefinition()
    {
        return definition;
    }




    // ==================================================
    // COUNTER STATE
    // ==================================================

    public Integer getLastKc()
    {
        return lastKc;
    }

    public void setLastKc(
            Integer lastKc)
    {
        this.lastKc =
                lastKc;
    }


    // ==================================================
    // DEFINITION SHORTCUTS
    // ==================================================

    public String getName()
    {
        return definition.getName();
    }

    public String getProfileKey()
    {
        return definition.getProfileKey();
    }

    public String getKcMessagePrefix()
    {
        return definition.getKcMessagePrefix();
    }

    public int getPendingWindowTicks()
    {
        return definition.getPendingWindowTicks();
    }

    public String getDetectorVersion()
    {
        return definition.getDetectorVersion();
    }

    public BossDetectorType getDetectorType()
    {
        return definition.getDetectorType();
    }

    public Integer getCompletionVarpId()
    {
        return definition.getCompletionVarpId();
    }
}

package com.huntmaster;

/** Assignment-scoped supporting NPC identities; never awards credit without personal KC. */
final class BossNpcAliases
{
    private BossNpcAliases() { }
    static boolean matches(String boss, String npc)
    {
        if (boss == null || npc == null) return false;
        if (boss.equalsIgnoreCase(npc)) return true;
        switch (boss)
        {
            case "Grotesque Guardians": return "Dusk".equalsIgnoreCase(npc) || "Dawn".equalsIgnoreCase(npc);
            case "Royal Titans": return "Branda the Fire Queen".equalsIgnoreCase(npc) || "Eldric the Ice King".equalsIgnoreCase(npc);
            case "The Nightmare": return "Nightmare".equalsIgnoreCase(npc);
            case "The Hueycoatl": return "Hueycoatl".equalsIgnoreCase(npc);
            case "The Mimic": return "Mimic".equalsIgnoreCase(npc);
            default: return false;
        }
    }
}

