package com.huntmaster;

import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Properties;

/** A packaged bot address; players cannot select another server. */
final class BotEndpoint
{
	static String resolve(boolean development, String publicAddress)
	{
		if (development) return "http://127.0.0.1:8787";
		if (publicAddress == null || publicAddress.trim().isEmpty()) return null;
		try
		{
			URI uri = new URI(publicAddress.trim());
			String host = uri.getHost();
			if (!"https".equals(uri.getScheme()) || host == null || host.indexOf('.') < 0
				|| "localhost".equalsIgnoreCase(host) || host.matches("[0-9.]+")
				|| host.indexOf(':') >= 0 || uri.getUserInfo() != null || uri.getPort() != -1
				|| uri.getQuery() != null || uri.getFragment() != null
				|| !(uri.getPath().isEmpty() || "/".equals(uri.getPath()))) return null;
			return "https://" + host;
		}
		catch (URISyntaxException ex) { return null; }
	}

	static String load(boolean development)
	{
		if (development) return resolve(true, null);
		Properties properties = new Properties();
		try (InputStream input = BotEndpoint.class.getResourceAsStream("/huntmaster-api.properties"))
		{
			if (input != null) properties.load(input);
			if (!Boolean.parseBoolean(properties.getProperty("publicReady", "false"))) return null;
			return resolve(false, properties.getProperty("botUrl"));
		}
		catch (IOException ex) { return null; }
	}
}

package com.huntmaster;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;

/** Reward-interface identity, not individual boss deaths. */
final class ChestCompletionAdapter
{
    static int rewardInventory(String boss, int interfaceId)
    {
        if ("Barrows Brothers".equalsIgnoreCase(boss) && interfaceId == InterfaceID.BARROWS_REWARD)
            return InventoryID.TRAIL_REWARDINV;
        if ("Moons of Peril".equalsIgnoreCase(boss) && interfaceId == InterfaceID.PMOON_REWARD)
            return InventoryID.PMOON_REWARDINV;
        return -1;
    }
}

package com.huntmaster;

import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;

/** Short-lived raw game-state snapshot. The server decides whether it qualifies. */
final class ChestRunState
{
 private static final int[] BARROWS = {VarbitID.BARROWS_KILLED_AHRIM, VarbitID.BARROWS_KILLED_DHAROK,
  VarbitID.BARROWS_KILLED_GUTHAN, VarbitID.BARROWS_KILLED_KARIL, VarbitID.BARROWS_KILLED_TORAG, VarbitID.BARROWS_KILLED_VERAC};
 private static final int[] MOONS = {VarbitID.PMOON_BOSS_BLOOD_DEAD, VarbitID.PMOON_BOSS_BLUE_DEAD, VarbitID.PMOON_BOSS_ECLIPSE_DEAD};
 private String context;
 private int mask;
 private int tick = -1;
 static int read(String boss, IntUnaryOperator read)
 {
  int[] ids;
  if ("Barrows Brothers".equals(boss)) ids = BARROWS;
  else if ("Moons of Peril".equals(boss)) ids = MOONS;
  else return -1;
  int result = 0;
  for (int i = 0; i < ids.length; i++) if (read.applyAsInt(ids[i]) > 0) result |= 1 << i;
  return result;
 }
 void sample(String key, int current, int now) { context = key; mask = current; tick = now; }
 int[] consume(String key, int current, int now)
 {
  int age = now - tick;
  int[] result = current >= 0 ? new int[] {current, 0} : null;
  // Allow the immediately preceding game tick when chest collection has just reset the flags.
  if (current == 0 && key.equals(context) && mask > 0 && age >= 0 && age <= 1) result = new int[] {mask, age};
  clear();
  return result;
 }
 void clear() { context = null; mask = 0; tick = -1; }
}

package com.huntmaster;

import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/** Bounded data only: the server can extend known capture windows, never select client reads. */
final class CollectionPolicy
{
    private Map<String, Integer> windows = Collections.emptyMap();
    private long expiresAt;
    private boolean supported;
    private boolean updateRequired;
    private boolean doomEvidence;
    private boolean encounterVariants;
    private boolean doomCounters;
    boolean supportsDoomCounters(long now) { return supportsDoomEvidence(now) && doomCounters; }
    boolean supportsEncounterVariants(long now) { return supported && now < expiresAt && encounterVariants; }
    boolean supportsDoomEvidence(long now) { return supported && now < expiresAt && doomEvidence; }
    private String revision="packaged-default";
    String revision(long now) { return now<expiresAt?revision:"packaged-default"; }
    boolean updateRequired() { return updateRequired; }
    void accept(JsonObject value, long now)
    {
        windows = Collections.emptyMap(); expiresAt = 0; supported = false;updateRequired=false;revision="packaged-default";doomEvidence=false;encounterVariants=false;doomCounters=false;
        try
        {
            if(value!=null && value.has("minimumVersion") && value.get("minimumVersion").getAsInt()>2){updateRequired=true;return;}
            if (value == null || !"2".equals(value.get("version").getAsString())) return;
            supported = true;
            long expiry = value.get("expiresAt").getAsLong();
            if (expiry <= now || expiry > now + 86_400_000L) return;
            JsonObject entries = value.getAsJsonObject("windows");
            if (entries == null || entries.size() > 64) return;
            Map<String, Integer> parsed = new HashMap<>();
            for (Map.Entry<String, com.google.gson.JsonElement> entry : entries.entrySet())
            {
                if (!java.util.Arrays.asList(SupportedEncounters.NAMES).contains(entry.getKey())) return;
                String raw = entry.getValue().getAsString();
                if (!raw.matches("[0-9]{1,3}")) return;
                int ticks = Integer.parseInt(raw);
                if (ticks < 10 || ticks > 128) return;
                parsed.put(entry.getKey(), ticks);
            }
            windows = parsed; expiresAt = expiry;
            doomEvidence = value.has("doomEvidenceVersion") && "1".equals(value.get("doomEvidenceVersion").getAsString());
            doomCounters = value.has("doomCounterEvidenceVersion") && "1".equals(value.get("doomCounterEvidenceVersion").getAsString());
            encounterVariants = value.has("encounterVariantVersion") && "1".equals(value.get("encounterVariantVersion").getAsString());
            if(value.has("revision") && value.get("revision").getAsString().matches("[a-zA-Z0-9_.-]{1,40}"))revision=value.get("revision").getAsString();
        }
        catch (RuntimeException ignored) { windows = Collections.emptyMap(); }
    }
    boolean supported() { return supported; }
    Map<String, Integer> windows(long now) { return now < expiresAt ? windows : Collections.emptyMap(); }
}

package com.huntmaster;

import com.google.gson.JsonObject;

/** Session-only, allowlisted support information; never includes account names or request bodies. */
final class CollectorDiagnostics
{
    static final String BUILD = "collector-v2-variants-1";
    private String encounter="none",variant="none";
    private DoomCompletionEvidence doom;
    private String doomCounters="none",doomCorrelation="none",doomAggregate="none";
    private String id = "none", outcome = "No reports this session", reason = "none", reportPolicy="none";
    void reset() { id="none"; outcome="No reports this session"; reason="none";reportPolicy="none";encounter="none";variant="none";doom=null;doomCounters="none";doomCorrelation="none";doomAggregate="none"; }
    void queued(String reportId) { queued(reportId,"packaged-default"); }
    void queued(String reportId,String revision) { id=java.util.UUID.fromString(reportId).toString(); outcome="Evidence queued"; reason="awaiting_delivery"; reportPolicy=token(revision);encounter="none";variant="none";doom=null;doomCounters="none";doomCorrelation="none";doomAggregate="none"; }
    void queued(EncounterObservation.Snapshot snapshot)
    {
        queued(snapshot.reportId.toString(),snapshot.policyRevision);
        // Canonical names are plugin-defined; never copy arbitrary account/chat metadata.
        if(java.util.Arrays.asList(SupportedEncounters.NAMES).contains(snapshot.boss))encounter=snapshot.boss;
        variant=snapshot.encounterVariant==null?"none":snapshot.encounterVariant.name();
        doom=snapshot.doomState;
        if(DoomCompletionEvidence.BOSS.equals(snapshot.boss))
        {
            for(EncounterObservation.Signal signal:snapshot.signals)
                if(signal.kind==EncounterObservation.SignalKind.COUNTER && signal.source==EncounterObservation.CounterSource.COMPLETION_VARP)
                    doomAggregate=signal.previous+" -> "+signal.current;
            if(snapshot.doomCounter!=null)
                doomCounters=snapshot.doomCounter.source.name()+": "+snapshot.doomCounter.previous+" -> "+snapshot.doomCounter.current;
            doomCorrelation=snapshot.doomState!=null && snapshot.doomCounter!=null ? "message and level counter paired"
                : snapshot.doomCounter!=null ? "level counter only" : snapshot.doomState!=null ? "message without level counter" : "aggregate only";
        }
    }
    void response(String reportId, boolean accepted, int http, JsonObject credit)
    {
        if (!id.equals(reportId)) return;
        if (!accepted) { outcome=http==400||http==409||http==413?"Evidence rejected by server":"Evidence not acknowledged"; reason="http_"+http; return; }
        String status=field(credit,"status");
        reason=credit!=null && credit.has("reason") ? field(credit,"reason") : status;
        outcome="progress_updated".equals(status)||"task_completed".equals(status) ? "Kill credited"
            : "unknown".equals(status) ? "Evidence received; credit unknown" : "Evidence received; no new credit";
    }
    private static String field(JsonObject object,String key)
    {
        try {
            String value=object.get(key).getAsString();
            return java.util.Arrays.asList("progress_updated","task_completed","pending_evidence","observation_only","no_assignment",
                "duplicate_counter","duplicate","boss_mismatch","assignment_invalidated","no_task","reports_blocked",
                "personal_counter_missing","capture_interrupted","full_clear_evidence_required","counter_or_encounter_support_insufficient",
                "supported_evidence","variant_evidence_required","tracking_mode_mismatch","credit_held").contains(value)?value:"unknown";
        } catch(RuntimeException ex){return "unknown";}
    }
    static String token(String value) { return value!=null && value.matches("[a-zA-Z0-9_.-]{1,80}") ? value : "unknown"; }
    String summary() { return outcome + ("none".equals(reason)?"":" ("+reason.replace('_',' ')+")"); }
    String copy(String state,int queued,String revision)
    {
        return "Huntmaster build: "+BUILD+"\nCollector: 2\nCollection: "+state+"\nQueued reports: "+queued
            +"\nCurrent policy: "+token(revision)+"\nLatest report: "+id+"\nReport policy: "+reportPolicy+"\nReport status: "+outcome+"\nReason: "+reason
            +"\nEncounter: "+encounter+"\nVariant: "+variant
            +(doom==null?"":"\nCompleted Level: "+doom.completedLevel+"\nExtended: "+(doom.extended?"yes":"no")+"\nSource: "+doom.source)
            +(DoomCompletionEvidence.BOSS.equals(encounter)?"\nDoom aggregate: "+doomAggregate+"\nDoom per-level: "+doomCounters+"\nDoom correlation: "+doomCorrelation:"");
    }
}

package com.huntmaster;

/** Outage time is independent of queued-event age and survives client restarts. */
final class ConnectionOutageState
{
	static final long GRACE_PERIOD_MS = 10 * 60 * 1000L;
	private long startedAt;

	void restore(long savedStartedAt, long now)
	{
		startedAt = savedStartedAt > 0 ? Math.min(savedStartedAt, now) : 0;
	}

	boolean fail(long now)
	{
		if (startedAt != 0)
		{
			return false;
		}
		startedAt = now;
		return true;
	}

	boolean isPaused(long now)
	{
		return startedAt != 0 && now - startedAt >= GRACE_PERIOD_MS;
	}

	long getStartedAt()
	{
		return startedAt;
	}

	void recover()
	{
		startedAt = 0;
	}
}

