}

package com.huntmaster;

import java.util.Objects;
import java.util.function.Consumer;

/** Separate counter state and bounded signal windows for each king; diagnostic only. */
final class DagannothComponentCollector
{
    private static final String[] NAMES = {"Dagannoth Rex", "Dagannoth Prime", "Dagannoth Supreme"};
    private static final String[] KEYS = {"rex", "prime", "supreme"};
    private final BossDetector[] detectors = new BossDetector[3];
    private final EncounterCapture[] captures = new EncounterCapture[3];
    private String scope;
    private int lastTick = -1;

    DagannothComponentCollector(Consumer<EncounterObservation.Snapshot> sink)
    {
        for (int i = 0; i < 3; i++)
        {
            detectors[i] = new BossDetector(BossDefinition.dagannothComponent(KEYS[i]));
            captures[i] = new EncounterCapture(sink);
        }
    }
    private void prepare(String rsn, String assignment, int tick)
    {
        String next = rsn + ":" + assignment;
        if (!Objects.equals(next, scope)) interrupt(tick, EncounterObservation.Reason.ASSIGNMENT_CHANGED);
        advance(tick);
        scope = next;
    }
    boolean counter(String message, String rsn, String assignment, int tick, long now)
    {
        for (int i = 0; i < 3; i++)
        {
            Integer total = GenericKcRouter.parse(message, NAMES[i]);
            if (total == null) continue;
            prepare(rsn, assignment, tick);
            Integer previous = detectors[i].getLastKc();
            captures[i].counter(detectors[i], rsn, assignment, tick, now,
                EncounterObservation.CounterSource.KC_MESSAGE, previous, total);
            if (previous != null && (long) total - previous != 1)
                captures[i].uncertain(EncounterObservation.Outcome.AMBIGUOUS);
            detectors[i].setLastKc(total);
            return true;
        }
        return false;
    }
    boolean npc(String name, boolean loot, String rsn, String assignment, int tick, long now)
    {
        for (int i = 0; i < 3; i++)
        {
            if (!NAMES[i].equalsIgnoreCase(name)) continue;
            prepare(rsn, assignment, tick);
            if (loot) captures[i].loot(detectors[i], rsn, assignment, tick, now);
            else captures[i].primary(detectors[i], rsn, assignment, tick, now, EncounterObservation.SignalKind.DEATH);
            return true;
        }
        return false;
    }
    void advance(int tick)
    {
        if (lastTick > tick) interrupt(tick, EncounterObservation.Reason.CLOCK_RESET);
        lastTick = tick;
        for (EncounterCapture capture : captures) capture.advance(tick);
    }
    void interrupt(int tick, EncounterObservation.Reason reason)
    {
        for (int i = 0; i < 3; i++)
        {
            captures[i].interrupt(tick, reason);
            detectors[i].setLastKc(null);
        }
        scope = null;
        lastTick = -1;
    }
    void clear()
    {
        for (int i = 0; i < 3; i++) { captures[i].clear(); detectors[i].setLastKc(null); }
        scope = null;
        lastTick = -1;
    }
}

package com.huntmaster;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;

/** Parsed game notification, not a credit decision. Never retains message text. */
final class DoomCompletionEvidence
{
    static final String BOSS = "Doom of Mokhaiotl";
    static final String DETECTOR_VERSION = "doom-completion-observation-v1";
    // The game displays 9+ as "8+ (actual level)". Do not mistake the 8 for the level.
    private static final String TIME = "(?:[0-9]{1,3}:)?[0-9]{1,2}:[0-5][0-9](?:\\.[0-9]{1,2})?";
    private static final Pattern MESSAGE = Pattern.compile(
        "^Delve level: ([1-8]|8\\+ \\(([1-9][0-9]{0,9})\\)) duration: "
        + TIME + "(?: \\(new personal best\\)|\\. Personal best: " + TIME + ")?\\.?$",
        Pattern.CASE_INSENSITIVE);

    final int completedLevel;
    final boolean extended;
    final String source;
    final int tickOffset;

    private DoomCompletionEvidence(int level, boolean extended, String source, int tickOffset)
    {
        this.completedLevel = level;
        this.extended = extended;
        this.source = source;
        this.tickOffset = tickOffset;
    }

    static DoomCompletionEvidence parse(ChatMessageType type, String message)
    {
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM) return null;
        if (message == null || message.length() > 512) return null;
        Matcher match = MESSAGE.matcher(Text.removeTags(message));
        if (!match.matches()) return null;
        try
        {
            boolean extended = match.group(2) != null;
            int level = Integer.parseInt(extended ? match.group(2) : match.group(1));
            if (extended && level < 9) return null;
            return new DoomCompletionEvidence(level, extended, type.name(), 0);
        }
        catch (NumberFormatException ignored) { return null; }
    }

    DoomCompletionEvidence at(int offset)
    {
        return new DoomCompletionEvidence(completedLevel, extended, source, offset);
    }
}

package com.huntmaster;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;

/** Fixed personal counter reads. A change is an observation, never a completion verdict. */
final class DoomLevelCounters
{
    enum Source
    {
        DOM_LEVEL_1_COMPLETIONS(VarPlayerID.DOM_LEVEL_1_COMPLETIONS, 1),
        DOM_LEVEL_2_COMPLETIONS(VarPlayerID.DOM_LEVEL_2_COMPLETIONS, 2),
        DOM_LEVEL_3_COMPLETIONS(VarPlayerID.DOM_LEVEL_3_COMPLETIONS, 3),
        DOM_LEVEL_4_COMPLETIONS(VarPlayerID.DOM_LEVEL_4_COMPLETIONS, 4),
        DOM_LEVEL_5_COMPLETIONS(VarPlayerID.DOM_LEVEL_5_COMPLETIONS, 5),
        DOM_LEVEL_6_COMPLETIONS(VarPlayerID.DOM_LEVEL_6_COMPLETIONS, 6),
        DOM_LEVEL_7_COMPLETIONS(VarPlayerID.DOM_LEVEL_7_COMPLETIONS, 7),
        DOM_LEVEL_8_COMPLETIONS(VarPlayerID.DOM_LEVEL_8_COMPLETIONS, 8),
        DOM_LEVEL_8_PLUS_COMPLETIONS(VarPlayerID.DOM_LEVEL_8_PLUS_COMPLETIONS, 9);
        final int varp, bucket;
        Source(int varp, int bucket) { this.varp=varp; this.bucket=bucket; }
        boolean matches(int level) { return bucket==9 ? level>=9 : level==bucket; }
    }
    static final class Observation
    {
        final Source source;
        final int previous, current, tickOffset;
        Observation(Source source, int previous, int current, int offset)
        {
            if(source==null || previous<0 || current<0 || offset<0 || offset>=128)
                throw new IllegalArgumentException("Invalid Doom counter observation");
            this.source=source; this.previous=previous; this.current=current; this.tickOffset=offset;
        }
        Observation at(int offset) { return new Observation(source,previous,current,offset); }
    }
    private final Map<Source,Integer> baselines=new HashMap<>();
    void reset() { baselines.clear(); }
    void sample(IntUnaryOperator read, boolean collecting, Consumer<Observation> sink)
    {
        for(Source source:Source.values())
        {
            int current=read.applyAsInt(source.varp);
            if(current<0) { baselines.remove(source); continue; }
            Integer previous=baselines.put(source,current);
            if(collecting && previous!=null && current!=previous)
                sink.accept(new Observation(source,previous,current,0));
        }
    }
}

package com.huntmaster;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;

/** Dedicated personal normal/awakened completion totals. Shared NPC IDs cannot identify the mode. */
final class Dt2CompletionEvidence
{
    static final String[] BOSSES = {"Duke Sucellus", "The Leviathan", "Vardorvis", "The Whisperer"};
    static final int[] NORMAL = {VarPlayerID.TOTAL_DUKE_SUCELLUS_KILLS, VarPlayerID.TOTAL_LEVIATHAN_KILLS,
        VarPlayerID.TOTAL_VARDORVIS_KILLS, VarPlayerID.TOTAL_WHISPERER_KILLS};
    static final int[] AWAKENED = {VarPlayerID.TOTAL_DUKE_SUCELLUS_AWAKENED_KILLS,
        VarPlayerID.TOTAL_LEVIATHAN_AWAKENED_KILLS, VarPlayerID.TOTAL_VARDORVIS_AWAKENED_KILLS,
        VarPlayerID.TOTAL_WHISPERER_AWAKENED_KILLS};
    static final class Completion
    {
        final String boss;
        final EncounterVariant variant;
        final int previous, current;
        Completion(String boss, EncounterVariant variant, int previous, int current)
        { this.boss= boss; this.variant=variant; this.previous=previous; this.current=current; }
    }
    private final Map<Integer, Integer> baselines = new HashMap<>();
    void reset() { baselines.clear(); }
    void sample(IntUnaryOperator read, boolean collecting, Consumer<Completion> sink)
    {
        for (int i=0; i<BOSSES.length; i++)
        {
            Completion normal=sample(BOSSES[i], EncounterVariant.NORMAL, NORMAL[i], read, collecting);
            Completion awakened=sample(BOSSES[i], EncounterVariant.AWAKENED, AWAKENED[i], read, collecting);
            // A simultaneous aggregate/awakened update is not evidence of a second normal kill.
            if(awakened!=null)sink.accept(awakened);
            else if(normal!=null)sink.accept(normal);
        }
    }
    private Completion sample(String boss, EncounterVariant variant, int varp, IntUnaryOperator read,
        boolean collecting)
    {
        int total=read.applyAsInt(varp);
        if (total<0) { baselines.remove(varp); return null; }
        Integer previous=baselines.put(varp,total);
        // Login synchronization, unchanged totals and decreases are not completions.
        // Preserve jumps as raw observations; only the bot may decide their meaning.
        if (collecting && previous!=null && total>previous)
            return new Completion(boss,variant,previous,total);
        return null;
    }
}

package com.huntmaster;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;

/** Client-thread diagnostic routing; never mutates verification state. */
final class EncounterCapture
{
	private final java.util.Map<String, EncounterCapture> channels;
	private EncounterCapture selected;
	private int configuredWindow;
    private String policyRevision="packaged-default";
    void revision(String value) { policyRevision=value; }
 private java.util.Map<String,Integer> windows=java.util.Collections.emptyMap();
 void windows(java.util.Map<String,Integer> value) { windows=value; }
	private final List<EncounterObservation> records = new ArrayList<>();
	private final EncounterSignalBuffer history = new EncounterSignalBuffer();
	private EncounterObservation current;
	private boolean primarySeen;
	private int primaryTick = -1;
	private Integer counterTotal;
	private boolean verdict;
	private String context;
	private int lastTick = -1;
	private final Consumer<EncounterObservation.Snapshot> sink;
	private int lastDoomMessageTick = -1;
	private int lastDoomLevel = -1;
	private final java.util.Map<DoomLevelCounters.Source,String> lastDoomCounters=new java.util.EnumMap<>(DoomLevelCounters.Source.class);
	EncounterCapture(Consumer<EncounterObservation.Snapshot> sink) { this(sink, true); }
 private EncounterCapture(Consumer<EncounterObservation.Snapshot> sink, boolean root) { this.sink=sink; channels=root?new java.util.LinkedHashMap<>():null; }
 private EncounterCapture channel(BossDetector d) {
  if (!channels.containsKey(d.getName())) { if(channels.size()>=96) throw new IllegalStateException("Capture capacity"); channels.put(d.getName(),new EncounterCapture(sink,false)); }
  selected=channels.get(d.getName()); selected.configuredWindow=windows.getOrDefault(d.getName(),configuredWindow); selected.policyRevision=policyRevision; return selected;
 }
 void select(BossDetector d) { if(channels!=null)channel(d); }
 void variantCompletion(BossDetector d,String rsn,String assignment,int tick,long now,
     EncounterVariant variant,int previous,int total) {
  if (!EncounterVariant.supports(d.getName()) || variant==null) throw new IllegalArgumentException("Invalid DT2 variant");
  // Separate channels prevent normal/awakened counters, NPC support and delayed events mixing.
  if(channels!=null) {
   String key=d.getName()+":"+variant.name();
   if(!channels.containsKey(key)) {
    if(channels.size()>=96)throw new IllegalStateException("Capture capacity");
    channels.put(key,new EncounterCapture(sink,false));
   }
   selected=channels.get(key);selected.configuredWindow=windows.getOrDefault(d.getName(),configuredWindow);
   selected.policyRevision=policyRevision;
   selected.variantCompletion(d,rsn,assignment,tick,now,variant,previous,total);return;
  }
  if(previous<0 || total<=previous)throw new IllegalArgumentException("Invalid completion counter");
  primary(d,rsn,assignment,tick,now,EncounterObservation.SignalKind.COMPLETION);
  current.variant(variant);
  counter(d,rsn,assignment,tick,now,EncounterObservation.CounterSource.COMPLETION_VARP,previous,total);
 }
 void notice(BossDetector d,String rsn,String assignment,int tick,long now,String source,Integer value) {
  if(channels!=null){channel(d).notice(d,rsn,assignment,tick,now,source,value);return;}
  ensure(d,rsn,assignment,tick,now).recordPrimary(EncounterObservation.SignalKind.DIAGNOSTIC,tick);
  diagnostic(source,value,tick);
 }

	private EncounterObservation ensure(BossDetector detector, String rsn, String assignment, int tick, long now)
	{
		return ensure(detector, rsn, assignment, tick, now, java.util.Collections.emptyList());
	}
	private EncounterObservation ensure(BossDetector detector, String rsn, String assignment, int tick, long now,
		List<EncounterSignalBuffer.Event> before)
	{
		advance(tick);
		String key = rsn + ":" + assignment + ":" + detector.getName();
		if (!key.equals(context))
		{
			interrupt(tick, EncounterObservation.Reason.ASSIGNMENT_CHANGED);
			context = key;
		}
		if (current == null || current.isClosed())
		{
			if (records.size() >= 8)
			{
				EncounterObservation oldest = records.remove(0);
				oldest.interrupt(tick, EncounterObservation.Reason.SIGNAL_LIMIT);
				sink.accept(oldest.snapshot());
			}
			int start = before.isEmpty() ? tick : before.get(0).tick;
			long time = before.isEmpty() ? now : before.get(0).time;
			current = new EncounterObservation(UUID.randomUUID(), assignment == null ? null : UUID.fromString(assignment), rsn,
				detector.getName(), detector.getDetectorType(), detector.getDetectorVersion(), time, start,
				Math.min(128, Math.max(configuredWindow,("The Nightmare".equals(detector.getName()) ? Math.max(24, detector.getPendingWindowTicks()) : detector.getPendingWindowTicks())) + tick - start), detector.getDefinition().isEvidenceOnly());
			for (EncounterSignalBuffer.Event event : before)
			{
				if (event.kind == EncounterObservation.SignalKind.LOOT)
					current.recordLoot(event.tick, EncounterObservation.LootAttribution.UNCERTAIN);
				else current.recordPrimary(event.kind, event.tick);
			}
			records.add(current);
            current.policyRevision=policyRevision;
			primarySeen = false;
			counterTotal = null;
			verdict = false;
		}
		return current;
	}
	void primary(BossDetector d, String rsn, String assignment, int tick, long now, EncounterObservation.SignalKind kind)
	{
		if(channels!=null){channel(d).primary(d,rsn,assignment,tick,now,kind);return;}
		if (current != null && primarySeen && primaryTick == tick && (rsn + ":" + assignment + ":" + d.getName()).equals(context)) return;
		// A new encounter must not inherit unconsumed support from a prior kill.
		history.clear();
		if (current != null && (primarySeen || verdict)) current = null;
		ensure(d, rsn, assignment, tick, now).recordPrimary(kind, tick);
		history.add(context, tick, now, kind);
		primarySeen = true;
		primaryTick = tick;
	}
	void counter(BossDetector d, String rsn, String assignment, int tick, long now,
		EncounterObservation.CounterSource source, Integer previous, int total)
	{
		if(channels!=null){channel(d).counter(d,rsn,assignment,tick,now,source,previous,total);return;}
		if (DoomCompletionEvidence.BOSS.equals(d.getName()))
		{
			// Initial synchronization is a baseline, never an encounter.
			if (source != EncounterObservation.CounterSource.COMPLETION_VARP || previous == null || previous == total) return;
			prepareDoomContext(rsn, assignment, tick);
			EncounterObservation target = doomPartner(tick, false, null, null);
			if (target == null) { current = null; target = ensure(d, rsn, assignment, tick, now); }
			target.recordCounter(tick, source, previous, total);
			return;
		}
		advance(tick);
		String key = rsn + ":" + assignment + ":" + d.getName();
		List<EncounterSignalBuffer.Event> before = history.consume(key, tick);
		if (current != null && counterTotal != null && counterTotal != total) current = null;
		ensure(d, rsn, assignment, tick, now, before).recordCounter(tick, source, previous, total);
		counterTotal = total;
	}

	void doomCompletion(BossDetector d, String rsn, String assignment, int tick, long now, DoomCompletionEvidence evidence)
	{
		if (channels != null) { channel(d).doomCompletion(d, rsn, assignment, tick, now, evidence); return; }
		if (!DoomCompletionEvidence.BOSS.equals(d.getName())) throw new IllegalArgumentException("Expected Doom detector");
		prepareDoomContext(rsn, assignment, tick);
		// The same notification can be repeated across game-message categories in one tick.
		if (lastDoomMessageTick == tick && lastDoomLevel == evidence.completedLevel) return;
		EncounterObservation target = doomPartner(tick, true, evidence, null);
		if (target == null) { current = null; target = ensure(d, rsn, assignment, tick, now); }
		target.recordDoomCompletion(evidence, tick);
		lastDoomMessageTick = tick;
		lastDoomLevel = evidence.completedLevel;
	}

	private void prepareDoomContext(String rsn, String assignment, int tick)
	{
		advance(tick);
		if (context != null && !context.equals(rsn + ":" + assignment + ":" + DoomCompletionEvidence.BOSS))
			interrupt(tick, EncounterObservation.Reason.ASSIGNMENT_CHANGED);
	}

	void doomCounter(BossDetector d, String rsn, String assignment, int tick, long now, DoomLevelCounters.Observation evidence)
	{
		if(channels!=null) { channel(d).doomCounter(d,rsn,assignment,tick,now,evidence); return; }
		if(!DoomCompletionEvidence.BOSS.equals(d.getName()))throw new IllegalArgumentException("Expected Doom detector");
		prepareDoomContext(rsn,assignment,tick);
		String identity=evidence.previous+":"+evidence.current;
		if(identity.equals(lastDoomCounters.get(evidence.source)))return;
		EncounterObservation target=doomPartner(tick,false,null,evidence);
		if(target==null) { current=null; target=ensure(d,rsn,assignment,tick,now); }
		target.recordDoomCounter(evidence,tick);
		lastDoomCounters.put(evidence.source,identity);
	}
	private EncounterObservation doomPartner(int tick, boolean message, DoomCompletionEvidence completion, DoomLevelCounters.Observation counter)
	{
		EncounterObservation candidate = null;
		for (EncounterObservation record : records)
		{
			if (!record.acceptsTick(tick)) continue;
			boolean compatible=message
				? !record.hasDoomCompletion() && (record.hasCounter() || record.hasDoomCounter()) && record.matchesDoomCounter(completion.completedLevel)
				: counter!=null
				? !record.hasDoomCounter() && (record.hasCounter() || record.hasDoomCompletion()) && record.matchesDoomLevel(counter.source)
				: !record.hasCounter() && (record.hasDoomCompletion() || record.hasDoomCounter());
			if(!compatible)continue;
			// Any other unmatched evidence makes the temporal association ambiguous.
			if (candidate != null) return null;
			candidate = record;
		}
		return candidate;
	}

	void interruptDoom(int tick)
	{
		if (channels == null) return;
		EncounterCapture doom = channels.get(DoomCompletionEvidence.BOSS);
		if (doom != null) doom.interrupt(tick, EncounterObservation.Reason.LOGOUT);
	}
	void interruptVariants(int tick)
	{
		if(channels==null)return;
		for(java.util.Map.Entry<String,EncounterCapture> entry:channels.entrySet())
			if(entry.getKey().endsWith(":NORMAL") || entry.getKey().endsWith(":AWAKENED"))
				entry.getValue().interrupt(tick,EncounterObservation.Reason.LOGOUT);
	}
	void loot(BossDetector d, String rsn, String assignment, int tick, long now)
	{
		if(channels!=null){channel(d).loot(d,rsn,assignment,tick,now);return;}
		EncounterObservation target = ensure(d, rsn, assignment, tick, now);
		// Once a counter is attached, subsequent loot belongs to that record only.
		if (counterTotal == null) history.add(context, tick, now, EncounterObservation.SignalKind.LOOT);
		target.recordLoot(tick, records.size() == 1 ? EncounterObservation.LootAttribution.MATCHING_ENCOUNTER
			: EncounterObservation.LootAttribution.UNCERTAIN);
	}
	void chestState(int mask, int age, int tick)
	{
		if(channels!=null){if(selected!=null)selected.chestState(mask,age,tick);return;}
		if (current != null && primarySeen && primaryTick == tick) current.recordChestState(mask, age, tick);
	}
	void diagnostic(String source, Integer total, int tick)
	{
		if(channels!=null){if(selected!=null)selected.diagnostic(source,total,tick);return;}
		if (current != null) current.diagnostic(source, total, tick);
	}
	void uncertain(EncounterObservation.Outcome outcome)
	{
		if(channels!=null){if(selected!=null)selected.uncertain(outcome);return;}
		if (current != null && !current.isClosed() && !verdict)
		{
			current.markUncertain(outcome, outcome == EncounterObservation.Outcome.AMBIGUOUS
				? EncounterObservation.Reason.COUNTER_JUMP : EncounterObservation.Reason.WINDOW_EXPIRED);
			verdict = true;
		}
	}
	void advance(int tick)
	{
		if(channels!=null){for(EncounterCapture c:channels.values())c.advance(tick);return;}
		if (lastTick > tick) interrupt(tick, EncounterObservation.Reason.CLOCK_RESET);
		lastTick = tick;
		java.util.Iterator<EncounterObservation> iterator = records.iterator();
		while (iterator.hasNext())
		{
			EncounterObservation record = iterator.next();
			record.closeIfExpired(tick);
			if (record.isClosed()) { iterator.remove(); sink.accept(record.snapshot()); }
		}
	}
	void interrupt(int tick, EncounterObservation.Reason reason)
	{
		if(channels!=null){for(EncounterCapture c:channels.values())c.interrupt(tick,reason);return;}
		for (EncounterObservation record : records)
		{
			record.interrupt(tick, reason);
			sink.accept(record.snapshot());
		}
		records.clear(); current = null; context = null;
		lastDoomMessageTick = -1; lastDoomLevel = -1;
		lastDoomCounters.clear();
		history.clear();
	}
	void clear() { if(channels!=null){for(EncounterCapture c:channels.values())c.clear();channels.clear();selected=null;return;} records.clear(); current = null; context = null; lastTick = -1; lastDoomMessageTick = -1; lastDoomLevel = -1; lastDoomCounters.clear(); history.clear(); }
}

package com.huntmaster;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

/** Pure diagnostic record. It never decides or awards Huntmaster credit. */
final class EncounterObservation
{
    String policyRevision="packaged-default";
	static final int MAX_SIGNALS = 32;
	static final int MAX_WINDOW_TICKS = 128;
	enum SignalKind { DEATH, COMPLETION, ACTIVITY_COMPLETION, COUNTER, LOOT, DIAGNOSTIC }
	enum CounterSource { KC_MESSAGE, RS_PROFILE, COMPLETION_VARP }
	enum LootAttribution { MATCHING_ENCOUNTER, UNCERTAIN }
	enum Outcome { UNRESOLVED, AMBIGUOUS, INTERRUPTED }
	enum Reason { WINDOW_EXPIRED, COUNTER_JUMP, LOGOUT, ASSIGNMENT_CHANGED, SHUTDOWN, SIGNAL_LIMIT, CLOCK_RESET }

	static final class Signal
	{
		final SignalKind kind;
		final int tickOffset;
		final CounterSource source;
		final Integer previous;
		final Integer current;
		final LootAttribution attribution;

		private Signal(SignalKind kind, int tickOffset, CounterSource source,
				Integer previous, Integer current, LootAttribution attribution)
		{
			this.kind = kind;
			this.tickOffset = tickOffset;
			this.source = source;
			this.previous = previous;
			this.current = current;
			this.attribution = attribution;
		}

		private boolean sameAs(Signal other)
		{
			return kind == other.kind && tickOffset == other.tickOffset && source == other.source
					&& Objects.equals(previous, other.previous) && Objects.equals(current, other.current)
					&& attribution == other.attribution;
		}
	}

	static final class Snapshot
	{
        final String policyRevision;
		final boolean evidenceOnly;
		final UUID reportId;
		final UUID assignmentId;
		final String rsn;
		final String boss;
		final BossDetectorType detectorType;
		final String detectorVersion;
		final long observedAt;
		final int windowTicks;
		final int durationTicks;
		final Outcome outcome;
		final Reason reason;
		final Reason interruptionReason;
		final boolean captureComplete;
		final List<Signal> signals;
		final int[] chestState;
		final DoomCompletionEvidence doomState;
		final DoomLevelCounters.Observation doomCounter;
		final EncounterVariant encounterVariant;
		final List<Diagnostic> diagnostics;

		private Snapshot(EncounterObservation record)
		{
            policyRevision=record.policyRevision;
			chestState = record.chestState == null ? null : record.chestState.clone();
			doomState = record.doomState;
			doomCounter = record.doomCounter;
			encounterVariant = record.encounterVariant;
			diagnostics = Collections.unmodifiableList(new ArrayList<>(record.diagnostics));
			evidenceOnly = record.evidenceOnly;
			reportId = record.reportId;
			assignmentId = record.assignmentId;
			rsn = record.rsn;
			boss = record.boss;
			detectorType = record.detectorType;
			detectorVersion = record.detectorVersion;
			observedAt = record.observedAt;
			windowTicks = record.windowTicks;
			durationTicks = record.durationTicks;
			outcome = record.outcome;
			reason = record.reason;
			interruptionReason = record.interruptionReason;
			captureComplete = record.interruptionReason == null;
			signals = Collections.unmodifiableList(new ArrayList<>(record.signals));
		}
	}

	private final boolean evidenceOnly;
	private final UUID reportId;
	private final UUID assignmentId;
	private final String rsn;
	private final String boss;
	private final BossDetectorType detectorType;
	private final String detectorVersion;
	private final long observedAt;
	private final int startTick;
	private final int windowTicks;
	private final List<Signal> signals = new ArrayList<>();
	private Outcome outcome;
	private Reason reason;
	private Reason interruptionReason;
	private int durationTicks;
	private int latestTickOffset;
	private boolean closed;
	private int[] chestState;
	private DoomCompletionEvidence doomState;
	private DoomLevelCounters.Observation doomCounter;
	boolean hasDoomCounter() { return doomCounter!=null; }
	boolean matchesDoomLevel(DoomLevelCounters.Source source) { return doomState==null || source.matches(doomState.completedLevel); }
	boolean matchesDoomCounter(int level) { return doomCounter==null || doomCounter.source.matches(level); }
	void recordDoomCounter(DoomLevelCounters.Observation evidence, int tick)
	{
		if(!DoomCompletionEvidence.BOSS.equals(boss) || doomCounter!=null || !acceptsTick(tick))
			throw new IllegalStateException("Invalid Doom counter context");
		doomCounter=evidence.at(offset(tick));
		// Marks collection of raw data, never manufactures COMPLETION or doomState.
		recordPrimary(SignalKind.DIAGNOSTIC,tick);
	}
	private EncounterVariant encounterVariant;
	void variant(EncounterVariant variant)
	{
		if (closed || !EncounterVariant.supports(boss) || variant == null
			|| encounterVariant != null && encounterVariant != variant)
			throw new IllegalArgumentException("Invalid encounter variant context");
		encounterVariant = variant;
	}
	boolean hasDoomCompletion() { return doomState != null; }
	boolean hasCounter() { return signals.stream().anyMatch(s -> s.kind == SignalKind.COUNTER); }
	boolean acceptsTick(int tick) { return !closed && offset(tick) >= 0; }
	void recordDoomCompletion(DoomCompletionEvidence evidence, int tick)
	{
		if (!DoomCompletionEvidence.BOSS.equals(boss) || doomState != null || !acceptsTick(tick))
			throw new IllegalStateException("Invalid Doom completion context");
		doomState = evidence.at(offset(tick));
		recordPrimary(SignalKind.COMPLETION, tick);
	}
	static final class Diagnostic
	{
		final String source;
		final int tickOffset;
		final Integer total;
		Diagnostic(String source, int tickOffset, Integer total) { this.source = source; this.tickOffset = tickOffset; this.total = total; }
	}
	private final List<Diagnostic> diagnostics = new ArrayList<>();
	void diagnostic(String source, Integer total, int tick)
	{
		if (total != null && total < 0) total = null;
		int offset = offset(tick);
		if (closed || offset < 0 || diagnostics.size() >= 8) return;
		for (Diagnostic d : diagnostics) if (d.source.equals(source) && d.tickOffset == offset && Objects.equals(d.total, total)) return;
		diagnostics.add(new Diagnostic(source, offset, total));
		latestTickOffset = Math.max(latestTickOffset, offset);
	}
	void recordChestState(int mask, int age, int tick) { if (!closed && chestState == null) chestState = new int[] {mask, age, offset(tick)}; }

	EncounterObservation(UUID reportId, UUID assignmentId, String rsn, String boss,
			BossDetectorType detectorType, String detectorVersion, long observedAt, int startTick, int windowTicks)
	{
		this(reportId, assignmentId, rsn, boss, detectorType, detectorVersion, observedAt, startTick, windowTicks, false);
	}

	EncounterObservation(UUID reportId, UUID assignmentId, String rsn, String boss,
			BossDetectorType detectorType, String detectorVersion, long observedAt, int startTick, int windowTicks, boolean evidenceOnly)
	{
		this.evidenceOnly = evidenceOnly;
		this.reportId = Objects.requireNonNull(reportId);
		this.assignmentId = assignmentId;
		this.rsn = text(rsn, 64);
		this.boss = text(boss, 128);
		this.detectorType = Objects.requireNonNull(detectorType);
		this.detectorVersion = text(detectorVersion, 128);
		if (observedAt <= 0 || startTick < 0 || windowTicks < 1 || windowTicks > MAX_WINDOW_TICKS)
		{
			throw new IllegalArgumentException("Invalid encounter observation bounds");
		}
		this.observedAt = observedAt;
		this.startTick = startTick;
		this.windowTicks = windowTicks;
	}

	private static String text(String value, int limit)
	{
		if (value == null || value.trim().isEmpty() || value.length() > limit)
		{
			throw new IllegalArgumentException("Invalid observation metadata");
		}
		return value;
	}

	boolean recordPrimary(SignalKind kind, int tick)
	{
		if (kind != SignalKind.DEATH && kind != SignalKind.COMPLETION && kind != SignalKind.ACTIVITY_COMPLETION && kind != SignalKind.DIAGNOSTIC)
		{
			throw new IllegalArgumentException("Expected a primary encounter signal");
		}
		for (Signal existing : signals)
		{
			if (existing.kind == kind)
			{
				// A later primary signal belongs in another record, not this kill.
				return false;
			}
		}
		return add(new Signal(kind, offset(tick), null, null, null, null));
	}

	boolean recordCounter(int tick, CounterSource source, Integer previous, int current)
	{
		Objects.requireNonNull(source);
		if (current < 0 || previous != null && previous < 0)
		{
			throw new IllegalArgumentException("Invalid counter total");
		}
		for (Signal existing : signals)
		{
			if (existing.kind == SignalKind.COUNTER && !Objects.equals(existing.current, current))
			{
				return false;
			}
		}
		return add(new Signal(SignalKind.COUNTER, offset(tick), source, previous, current, null));
	}

	boolean recordLoot(int tick, LootAttribution attribution)
	{
		return add(new Signal(SignalKind.LOOT, offset(tick), null, null, null, Objects.requireNonNull(attribution)));
	}

	private int offset(int tick)
	{
		long offset = (long) tick - startTick;
		return offset < 0 || offset >= windowTicks ? -1 : (int) offset;
	}

	private boolean add(Signal signal)
	{
		if (closed || signal.tickOffset < 0)
		{
			return false;
		}
		for (Signal existing : signals)
		{
			if (existing.sameAs(signal))
			{
				return false;
			}
		}
		if (signals.size() >= MAX_SIGNALS)
		{
			interrupt(startTick + signal.tickOffset, Reason.SIGNAL_LIMIT);
			return false;
		}
		signals.add(signal);
		latestTickOffset = Math.max(latestTickOffset, signal.tickOffset);
		return true;
	}

	void markUncertain(Outcome outcome, Reason reason)
	{
		if (outcome != Outcome.UNRESOLVED && outcome != Outcome.AMBIGUOUS
				|| reason != Reason.WINDOW_EXPIRED && reason != Reason.COUNTER_JUMP)
		{
			throw new IllegalArgumentException("Invalid uncertain verdict");
		}
		setVerdict(outcome, reason);
	}

	private void setVerdict(Outcome outcome, Reason reason)
	{
		if (closed || this.outcome != null)
		{
			throw new IllegalStateException("Encounter verdict already fixed");
		}
		this.outcome = outcome;
		this.reason = reason;
	}

	boolean closeIfExpired(int tick)
	{
		if (closed || (long) tick - startTick < windowTicks)
		{
			return false;
		}
		if (outcome == null)
		{
			outcome = Outcome.UNRESOLVED;
			reason = Reason.WINDOW_EXPIRED;
		}
		durationTicks = windowTicks;
		closed = true;
		return true;
	}

	void interrupt(int tick, Reason interruption)
	{
		if (interruption != Reason.LOGOUT && interruption != Reason.ASSIGNMENT_CHANGED
				&& interruption != Reason.SHUTDOWN && interruption != Reason.SIGNAL_LIMIT && interruption != Reason.CLOCK_RESET)
		{
			throw new IllegalArgumentException("Invalid capture interruption");
		}
		if (closed)
		{
			return;
		}
		interruptionReason = interruption;
		if (outcome == null)
		{
			outcome = Outcome.INTERRUPTED;
			reason = interruption;
		}
		durationTicks = (int) Math.min(windowTicks, Math.max(latestTickOffset, (long) tick - startTick));
		closed = true;
	}

	boolean isClosed() { return closed; }

	Snapshot snapshot()
	{
		if (!closed)
		{
			throw new IllegalStateException("Capture must be finalized before reporting");
		}
		return new Snapshot(this);
	}
}

package com.huntmaster;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.Locale;

final class EncounterReportCodec
{
	private static final java.time.format.DateTimeFormatter TIMESTAMP =
		new java.time.format.DateTimeFormatterBuilder().appendInstant(3).toFormatter();
	private EncounterReportCodec() { }
	static String deliveryRoute(JsonObject report)
	{
		return report.has("trackingMode") && !report.get("trackingMode").isJsonNull()
			&& "server_observation".equals(report.get("trackingMode").getAsString())
			? "/api/runelite/observations" : "/api/runelite/encounter-reports";
	}
	private static JsonObject encodeSignals(EncounterObservation.Snapshot s)
	{
		JsonObject body = new JsonObject();
		body.addProperty("schemaVersion", 1);
		body.addProperty("collectorVersion", "2");
        body.addProperty("pluginBuild", CollectorDiagnostics.BUILD);
        body.addProperty("collectionPolicyRevision", s.policyRevision);
		body.addProperty("trackingMode", "server_observation");
		body.addProperty("reportId", s.reportId.toString());
		body.addProperty("assignmentId", s.assignmentId == null ? null : s.assignmentId.toString());
		body.addProperty("rsn", s.rsn);
		body.addProperty("boss", s.boss);
		body.addProperty("detectorType", s.detectorType.name());
		body.addProperty("detectorVersion", s.detectorVersion);
		body.addProperty("observedAt", TIMESTAMP.format(Instant.ofEpochMilli(s.observedAt)));
		body.addProperty("durationTicks", s.durationTicks);
		body.addProperty("windowTicks", s.windowTicks);
		body.addProperty("outcome", lower(s.outcome));
		body.addProperty("captureStatus", s.captureComplete ? "complete" : "interrupted");
		body.addProperty("reason", lower(s.reason));
		if (s.interruptionReason != null) body.addProperty("interruptionReason", lower(s.interruptionReason));
		JsonArray signals = new JsonArray();
		for (EncounterObservation.Signal signal : s.signals)
		{
			JsonObject item = new JsonObject();
			item.addProperty("kind", lower(signal.kind));
			item.addProperty("tickOffset", signal.tickOffset);
			if (signal.source != null)
			{
				item.addProperty("source", lower(signal.source));
				if (signal.previous == null) item.add("previous", JsonNull.INSTANCE);
				else item.addProperty("previous", signal.previous);
				item.addProperty("current", signal.current);
			}
			if (signal.attribution != null) item.addProperty("attribution", lower(signal.attribution));
			signals.add(item);
		}
		body.add("signals", signals);
		return body;
	}
	static JsonObject encodeObservation(EncounterObservation.Snapshot snapshot)
	{
		return encodeObservation(snapshot, true);
	}
	static JsonObject encodeObservation(EncounterObservation.Snapshot snapshot, boolean variantSupported)
	{
		return encodeObservation(snapshot,variantSupported,true);
	}
	static JsonObject encodeObservation(EncounterObservation.Snapshot snapshot, boolean variantSupported, boolean doomCountersSupported)
	{
		JsonObject body = encodeSignals(snapshot);
		if (snapshot.encounterVariant != null)
		{
			if (!EncounterVariant.supports(snapshot.boss)) throw new IllegalArgumentException("Invalid variant boss");
			// Normal legacy delivery remains available. Never erase AWAKENED identity.
			if (variantSupported || snapshot.encounterVariant == EncounterVariant.AWAKENED)
				body.addProperty("encounterVariant", snapshot.encounterVariant.name());
		}
		JsonObject diagnostics = new JsonObject();
		diagnostics.addProperty("version", 1);
		JsonArray counters = new JsonArray();
		for (EncounterObservation.Diagnostic d : snapshot.diagnostics)
		{
			JsonObject item = new JsonObject();
			item.addProperty("source", d.source);
			item.addProperty("tickOffset", d.tickOffset);
			if (d.total == null) item.add("total", JsonNull.INSTANCE); else item.addProperty("total", d.total);
			counters.add(item);
		}
		diagnostics.add("counters", counters);
		body.add("diagnostics", diagnostics);
		if (snapshot.doomState != null)
		{
			DoomCompletionEvidence evidence = snapshot.doomState;
			JsonObject doom = new JsonObject();
			doom.addProperty("version", 1);
			doom.addProperty("completedLevel", evidence.completedLevel);
			doom.addProperty("extended", evidence.extended);
			doom.addProperty("source", evidence.source);
			doom.addProperty("completionMessageObserved", true);
			doom.addProperty("tickOffset", evidence.tickOffset);
			body.add("doomState", doom);
		}
		if(snapshot.doomCounter!=null && doomCountersSupported)
		{
			DoomLevelCounters.Observation evidence=snapshot.doomCounter;
			JsonObject counter=new JsonObject();
			counter.addProperty("source",evidence.source.name());
			counter.addProperty("previous",evidence.previous);
			counter.addProperty("current",evidence.current);
			counter.addProperty("tickOffset",evidence.tickOffset);
			JsonObject countersState=new JsonObject(); countersState.addProperty("version",1);
			JsonArray observations=new JsonArray(); observations.add(counter);
			countersState.add("counters",observations); body.add("doomCounters",countersState);
		}
        if (snapshot.chestState != null) {
            JsonObject chest = new JsonObject();
            chest.addProperty("version", 1);
            chest.addProperty("mask", snapshot.chestState[0]);
            chest.addProperty("ageTicks", snapshot.chestState[1]);
            chest.addProperty("tickOffset", snapshot.chestState[2]);
            body.add("chestState", chest);
        }
		body.addProperty("outcome", snapshot.captureComplete ? "unresolved" : "interrupted");
		body.addProperty("reason", snapshot.captureComplete ? "window_expired" : lower(snapshot.interruptionReason));
		return body;
	}
	private static String lower(Enum<?> value) { return value.name().toLowerCase(Locale.ROOT); }
}

package com.huntmaster;

import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;

final class EncounterReportQueue
{
	static final long RETENTION_MS = 24 * 60 * 60 * 1000L;
	static final int MAX_REPORTS = 100;
	static final int MAX_BYTES = 1024 * 1024;
	static final class Entry
	{
		String id;
		String payload;
		long createdAt;
		long nextAttemptAt;
		boolean creditCandidate;
		transient boolean inFlight;
	}
	private final Map<String, Entry> entries = new LinkedHashMap<>();
	private long revision;
	private long payloadBytes;
	private int diagnosticCount;
	long revision() { return revision; }
	// Stop new collection before a persistent outage can grow memory indefinitely.
	// Already captured/saved events always remain deliverable.
	boolean collectionBackpressured() { return entries.size() >= 1000 || payloadBytes >= 8L * MAX_BYTES; }
	boolean add(String id, String payload, long createdAt, long now)
	{
		return add(id, payload, createdAt, now, false);
	}
	boolean add(String id, String payload, long createdAt, long now, boolean creditCandidate)
	{
		prune(now);
		if (id == null || payload == null || createdAt <= 0 || createdAt > now || (!creditCandidate && now - createdAt >= RETENTION_MS)
			|| entries.containsKey(id)) return false;
		int size = payload.getBytes(StandardCharsets.UTF_8).length;
		if (size > 8192) return false;
		// Credit delivery has the same durable semantics as pending verified KC.
		// Diagnostic retention and capacity must never discard a saved kill.
		if (!creditCandidate && (diagnosticCount >= MAX_REPORTS || payloadBytes + size > MAX_BYTES)) return false;
		Entry entry = new Entry(); entry.id = id; entry.payload = payload; entry.createdAt = createdAt;
		entry.creditCandidate = creditCandidate;
		entries.put(id, entry);
		payloadBytes += size;
		if (!creditCandidate) diagnosticCount++;
		revision++;
		return true;
	}
	void prune(long now)
	{
		java.util.Iterator<Entry> iterator = entries.values().iterator();
		while (iterator.hasNext())
		{
			Entry entry = iterator.next();
			if (!entry.creditCandidate && now - entry.createdAt >= RETENTION_MS)
			{
				iterator.remove();
				removed(entry);
			}
		}
	}
	Entry next(long now) { return next(now, entry -> true); }
	Entry next(long now, java.util.function.Predicate<Entry> eligible)
	{
		prune(now);
		// One diagnostic request at a time, independently of KC delivery.
		if (entries.values().stream().anyMatch(entry -> entry.inFlight)) return null;
		for (Entry entry : entries.values()) if (entry.creditCandidate && entry.nextAttemptAt <= now && eligible.test(entry)) return entry;
		for (Entry entry : entries.values()) if (entry.nextAttemptAt <= now && eligible.test(entry)) return entry;
		return null;
	}
	private void removed(Entry entry)
	{
		payloadBytes -= entry.payload.getBytes(StandardCharsets.UTF_8).length;
		if (!entry.creditCandidate) diagnosticCount--;
		revision++;
	}
	void acknowledge(String id)
	{
		Entry entry = entries.remove(id);
		if (entry != null) removed(entry);
	}
	void clear()
	{
		if (entries.isEmpty()) return;
		entries.clear(); payloadBytes = 0; diagnosticCount = 0; revision++;
	}
	void releaseInFlight() { entries.values().forEach(entry -> entry.inFlight = false); }
	Entry[] snapshot() { return entries.values().toArray(new Entry[0]); }
}

package com.huntmaster;

import java.util.*;

/** Small diagnostic history. Contains no chat, location, items, or other-player information. */
final class EncounterSignalBuffer
{
    static final int HISTORY_TICKS = 16;
    static final int MAX_EVENTS = 64;
    static final class Event
    {
        final int tick;
        final long time;
        final EncounterObservation.SignalKind kind;
        Event(int tick, long time, EncounterObservation.SignalKind kind)
        { this.tick = tick; this.time = time; this.kind = kind; }
    }
    private final List<Event> events = new ArrayList<>();
    private String context;
    void add(String key, int tick, long time, EncounterObservation.SignalKind kind)
    {
        prune(key, tick);
        if (!events.isEmpty())
        {
            Event last = events.get(events.size()-1);
            if (last.tick == tick && last.kind == kind) return;
        }
        if (events.size() == MAX_EVENTS) events.remove(0);
        events.add(new Event(tick, time, kind));
    }
    List<Event> consume(String key, int tick)
    {
        prune(key, tick);
        List<Event> result = new ArrayList<>(events);
        events.clear();
        return result;
    }
    private void prune(String key, int tick)
    {
        if (!Objects.equals(context, key) || (!events.isEmpty() && events.get(events.size()-1).tick > tick)) clear();
        context = key;
        events.removeIf(event -> tick-event.tick > HISTORY_TICKS);
    }
    void clear() { events.clear(); context = null; }
}

package com.huntmaster;

/** Bounded objective observations, never a Hunt classification. */
enum EncounterVariant
{
    NORMAL, AWAKENED;

    static boolean supports(String boss)
    {
        return "Duke Sucellus".equals(boss) || "The Leviathan".equals(boss)
            || "Vardorvis".equals(boss) || "The Whisperer".equals(boss);
    }
}

package com.huntmaster;

import java.util.Locale;
import java.util.regex.*;
import net.runelite.client.util.Text;

/** Conservative counterpart to RuneLite Chat Commands' shared personal-counter parser. */
final class GenericKcRouter
{
    private static final String COUNTER_PREFIX =
        "^Your (?:completion count for |subdued |completed )?(.+?) (?:kill |harvest |completion |success )?(?:count )?is:";
    private static final Pattern COUNTER = Pattern.compile(
        COUNTER_PREFIX + " ?([0-9][0-9,]*)(?:\\.|$|\\s)", Pattern.CASE_INSENSITIVE);
    private static final Pattern COUNTER_IDENTITY = Pattern.compile(COUNTER_PREFIX, Pattern.CASE_INSENSITIVE);

    // Keep the exact encounter identity even when its counter value is unreadable.
    static boolean identifies(String message, String boss)
    {
        if (!eligible(boss) || message == null || message.length() > 1024) return false;
        Matcher match = COUNTER_IDENTITY.matcher(Text.removeTags(message));
        return match.find() && BossCounterAliases.matches(boss, match.group(1).trim());
    }
    static boolean eligible(String assignedBoss)
    {
        if (assignedBoss == null || assignedBoss.trim().isEmpty()) return false;
        String name = assignedBoss.toLowerCase(Locale.ROOT);
        return !name.contains("chambers of xeric") && !name.contains("theatre of blood")
            && !name.contains("tombs of amascut");
    }
    static Integer parse(String message, String assignedBoss)
    {
        if (!eligible(assignedBoss) || message == null || message.length() > 1024) return null;
        Matcher match = COUNTER.matcher(Text.removeTags(message));
        if (!match.find() || !BossCounterAliases.matches(assignedBoss, match.group(1).trim())) return null;
        try { return Integer.valueOf(match.group(2).replace(",", "")); }
        catch (NumberFormatException ex) { return null; }
    }
}

package com.huntmaster;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import okhttp3.ResponseBody;

/** Bounded response handling and conservative retry classification. */
final class HttpResponsePolicy
{
    static final int MAX_RESPONSE_BYTES = 65536;
    private HttpResponsePolicy() { }
    static String read(ResponseBody body) throws IOException
    {
        if (body == null) return "";
        if (body.contentLength() > MAX_RESPONSE_BYTES) throw new IOException("Oversized Huntmaster response");
        try (InputStream input = body.byteStream())
        {
            byte[] bytes = input.readNBytes(MAX_RESPONSE_BYTES + 1);
            if (bytes.length > MAX_RESPONSE_BYTES) throw new IOException("Oversized Huntmaster response");
            return new String(bytes, StandardCharsets.UTF_8);
        }
    }
    static boolean isPermanentRejection(int status)
    {
        return status == 400 || status == 404 || status == 409 || status == 413 || status == 422;
    }
}

