package com.huntmaster;

import org.junit.Test;
import static org.junit.Assert.*;

public class ConnectionOutageStateTest
{
	private static final long START = 1_000_000L;

	@Test
	public void connectedStateDoesNotPause()
	{
		assertFalse(new ConnectionOutageState().isPaused(Long.MAX_VALUE));
	}

	@Test
	public void repeatedFailuresDoNotExtendGracePeriod()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		assertTrue(state.fail(START));
		assertFalse(state.fail(START + 30_000));
		assertEquals(START, state.getStartedAt());
		assertFalse(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS - 1));
		assertTrue(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS));
	}

	@Test
	public void restartPreservesRemainingGracePeriod()
	{
		ConnectionOutageState restored = new ConnectionOutageState();
		restored.restore(START, START + 5 * 60_000);
		assertEquals(START, restored.getStartedAt());
		assertFalse(restored.isPaused(START + 9 * 60_000));
		assertTrue(restored.isPaused(START + 10 * 60_000));
	}

	@Test
	public void restartAfterDeadlineStaysPaused()
	{
		ConnectionOutageState restored = new ConnectionOutageState();
		restored.restore(START, START + 20 * 60_000);
		assertTrue(restored.isPaused(START + 20 * 60_000));
	}

	@Test
	public void recoveryStartsFreshGracePeriodForNextOutage()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		state.fail(START);
		state.recover();
		assertEquals(0, state.getStartedAt());
		assertFalse(state.isPaused(START + 20 * 60_000));
		assertTrue(state.fail(START + 30 * 60_000));
		assertFalse(state.isPaused(START + 39 * 60_000));
	}

	@Test
	public void invalidRestoredTimestampsDoNotBreakDeadline()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		state.restore(-1, START);
		assertEquals(0, state.getStartedAt());
		state.restore(START + 60_000, START);
		assertEquals(START, state.getStartedAt());
		assertTrue(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS));
	}
}

package com.huntmaster;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;
import static org.junit.Assert.*;

public class CounterIdentityRoutingTest
{
    @Test public void everyPackagedCounterIdentityHasExactlyOneOwner()
    {
        for (String boss : SupportedEncounters.NAMES)
        {
            assertOwner("Your " + boss + " kill count is: unknown", boss);
            assertOwner("Your " + boss + " kill count is: 123.", boss);
        }
        for (BossDetector detector : BossRegistry.createDetectors())
            assertOwner(detector.getKcMessagePrefix() + " unknown", detector.getName());
    }

    private void assertOwner(String message, String expected)
    {
        Set<String> owners = new HashSet<>();
        for (String boss : SupportedEncounters.NAMES)
            if (CounterMessageEvidence.related(message, boss)) owners.add(boss);
        assertEquals(message, java.util.Collections.singleton(expected), owners);
    }

    @Test public void aliasesAndMalformedValuesKeepExactIdentity()
    {
        String[][] pairs = {{"Gauntlet", "The Gauntlet"}, {"Corrupted Gauntlet", "The Corrupted Gauntlet"},
            {"Nightmare", "The Nightmare"}, {"Phosani's Nightmare", "Phosani's Nightmare"},
            {"Barrows chest", "Barrows Brothers"}, {"Barrows Chests", "Barrows Brothers"},
            {"Lunar Chest", "Moons of Peril"}, {"Lunar Chests", "Moons of Peril"},
            {"Hueycoatl", "The Hueycoatl"}, {"Mimic", "The Mimic"},
            {"Leviathan", "The Leviathan"}, {"Whisperer", "The Whisperer"}};
        for (String[] pair : pairs)
            for (String value : new String[]{"123.", "unknown", "999999999999999999999"})
                assertOwner("Your <col=ff0000>" + pair[0] + "</col> completion count is: " + value, pair[1]);
        assertOwner("Your subdued Wintertodt count is: unknown", "Wintertodt");
        assertOwner("Your completed Gauntlet count is: unknown", "The Gauntlet");
    }

    private ImmediateReportDeliveryTest.Harness harness(String assignment) throws Exception
    {
        ImmediateReportDeliveryTest.Harness h = new ImmediateReportDeliveryTest.Harness();
        ImmediateReportDeliveryTest.set(h.plugin, "connectionInitialized", true);
        ImmediateReportDeliveryTest.set(h.plugin, "reliabilityRsn", "Example");
        ImmediateReportDeliveryTest.set(h.plugin, "assignedBoss", assignment);
        ImmediateReportDeliveryTest.set(h.plugin, "assignmentId", assignment == null ? null : h.assignment);
        // A real, unloaded ConfigManager returns unknown profile counters. Its scheduler
        // is inert so this fixture neither starts threads nor touches player settings.
        java.lang.reflect.Constructor<?> constructor = net.runelite.client.config.ConfigManager.class.getDeclaredConstructors()[0];
        constructor.setAccessible(true);
        Object[] dependencies = new Object[constructor.getParameterCount()];
        Class<?>[] types = constructor.getParameterTypes();
        for (int i = 0; i < types.length; i++)
        {
            if (types[i] == java.util.concurrent.ScheduledExecutorService.class)
                dependencies[i] = java.lang.reflect.Proxy.newProxyInstance(types[i].getClassLoader(), new Class[]{types[i]}, (p, m, a) -> null);
            else if (types[i] == Gson.class) dependencies[i] = new Gson();
            else if (types[i] == net.runelite.client.eventbus.EventBus.class) dependencies[i] = new net.runelite.client.eventbus.EventBus();
        }
        Object config = constructor.newInstance(dependencies);
        Class<?> dataType = Class.forName("net.runelite.client.config.ConfigData");
        java.lang.reflect.Constructor<?> dataConstructor = dataType.getDeclaredConstructor(java.io.File.class);
        dataConstructor.setAccessible(true);
        java.lang.reflect.Field profile = net.runelite.client.config.ConfigManager.class.getDeclaredField("configProfile");
        profile.setAccessible(true);
        profile.set(config, dataConstructor.newInstance(new java.io.File(System.getProperty("huntmaster.testHome"), "routing.properties")));
        ImmediateReportDeliveryTest.set(h.plugin, "configManager", config);
        return h;
    }

    private void send(ImmediateReportDeliveryTest.Harness h, String name, String value)
    {
        ChatMessage event = new ChatMessage();
        event.setType(ChatMessageType.GAMEMESSAGE);
        event.setMessage("Your " + name + " completion count is: " + value);
        h.plugin.onChatMessage(event);
    }

    private Set<String> finish(ImmediateReportDeliveryTest.Harness h) throws Exception
    {
        assertEquals(0L, ImmediateReportDeliveryTest.field("collectionCaptureFailures").getLong(h.plugin));
        ((EncounterCapture)ImmediateReportDeliveryTest.field("encounterCapture").get(h.plugin)).advance(400);
        Set<String> bosses = new HashSet<>();
        for (EncounterReportQueue.Entry entry : h.queue.snapshot())
        {
            JsonObject report = new Gson().fromJson(entry.payload, JsonObject.class);
            assertEquals("Example", report.get("rsn").getAsString());
            assertTrue("Duplicate report for same boss", bosses.add(report.get("boss").getAsString()));
        }
        return bosses;
    }

    @Test public void chatEventsNeverCreateSecondaryGauntletDiagnostics() throws Exception
    {
        for (String assignment : new String[]{null, "The Gauntlet", "Nex"})
            for (String value : new String[]{"123.", "unknown"})
            {
                ImmediateReportDeliveryTest.Harness h = harness(assignment);
                send(h, "Corrupted Gauntlet", value);
                assertEquals(java.util.Collections.singleton("The Corrupted Gauntlet"), finish(h));
            }
    }

    @Test public void independentOverlappingNotificationsKeepSeparateCaptures() throws Exception
    {
        ImmediateReportDeliveryTest.Harness h = harness(null);
        for (String name : new String[]{"Gauntlet", "Corrupted Gauntlet", "Nightmare", "Phosani's Nightmare"})
            send(h, name, "unknown");
        assertEquals(new HashSet<>(java.util.Arrays.asList("The Gauntlet", "The Corrupted Gauntlet",
            "The Nightmare", "Phosani's Nightmare")), finish(h));
    }

    @Test public void arbitraryTextCannotBorrowKnownBossNames() throws Exception
    {
        ImmediateReportDeliveryTest.Harness h = harness(null);
        for (String name : new String[]{"Baby Giant Mole", "Royal Titans impostor", "Unknown Nightmare"})
            send(h, name, "unknown");
        assertTrue(finish(h).isEmpty());
        assertFalse(CounterMessageEvidence.related("Your message about Nightmare count", "The Nightmare"));
        assertNull(GenericKcRouter.parse("Your Kraken kill count is: 999999999999999999", "Kraken"));
        assertEquals(Integer.valueOf(1234), GenericKcRouter.parse(
            "Your <col=ff0000>Sarachnis</col> kill count is: 1,234. Fight duration: 0:45", "Sarachnis"));
    }

    @Test public void npcAliasesHaveOneOwnerAcrossAllPackagedEncounters()
    {
        for (String boss : SupportedEncounters.NAMES) assertNpcOwner(boss, boss);
        String[][] aliases = {{"Dawn", "Grotesque Guardians"}, {"Dusk", "Grotesque Guardians"},
            {"Branda the Fire Queen", "Royal Titans"}, {"Eldric the Ice King", "Royal Titans"},
            {"Nightmare", "The Nightmare"}, {"Hueycoatl", "The Hueycoatl"}, {"Mimic", "The Mimic"}};
        for (String[] pair : aliases) assertNpcOwner(pair[0], pair[1]);
    }

    private void assertNpcOwner(String npc, String expected)
    {
        Set<String> owners = new HashSet<>();
        for (String boss : SupportedEncounters.NAMES)
            if (BossNpcAliases.matches(boss, npc)) owners.add(boss);
        assertEquals(npc, java.util.Collections.singleton(expected), owners);
    }

    @Test public void deathAndLootKeepTheirActualBossWhileOffAssignment() throws Exception
    {
        ImmediateReportDeliveryTest.Harness h = harness("Artio");
        for (String name : new String[]{"Artio", "Callisto"})
        {
            net.runelite.api.NPC npc = (net.runelite.api.NPC) java.lang.reflect.Proxy.newProxyInstance(
                net.runelite.api.NPC.class.getClassLoader(), new Class[]{net.runelite.api.NPC.class},
                (p, m, a) -> m.getName().equals("getName") ? name : m.getName().equals("getId") ? 1 : null);
            h.plugin.onActorDeath(new net.runelite.api.events.ActorDeath(npc));
            h.plugin.onNpcLootReceived(new net.runelite.client.events.NpcLootReceived(npc, java.util.Collections.emptyList()));
        }
        assertEquals(new HashSet<>(java.util.Arrays.asList("Artio", "Callisto")), finish(h));
        for (EncounterReportQueue.Entry entry : h.queue.snapshot())
        {
            JsonObject report = new Gson().fromJson(entry.payload, JsonObject.class);
            assertEquals(h.assignment, report.get("assignmentId").getAsString());
            assertEquals(2, report.getAsJsonArray("signals").size());
        }
    }
}

package com.huntmaster;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class DagannothComponentCollectorTest
{
    @Test public void interleavedIdenticalTotalsHaveSeparateBaselinesAndEvidenceOnlyReports()
    {
        List<EncounterObservation.Snapshot> reports = new ArrayList<>();
        DagannothComponentCollector c = new DagannothComponentCollector(reports::add);
        String id = UUID.randomUUID().toString();
        String[] names = {"Rex", "Prime", "Supreme"};
        for (String name : names)
        {
            assertTrue(c.npc("Dagannoth " + name, false, "Example", id, 100, 1000));
        }
        for (String name : names)
        {
            assertTrue(c.counter("Your Dagannoth " + name + " kill count is: 50.", "Example", id, 101, 1600));
        }
        for (String name : names)
        {
            assertTrue(c.npc("Dagannoth " + name, true, "Example", id, 102, 2200));
        }
        c.advance(110);
        assertEquals(3, reports.size());
        assertEquals(3, reports.stream().map(r -> r.detectorVersion).distinct().count());
        for (EncounterObservation.Snapshot r : reports)
        {
            assertEquals("Dagannoth Kings", r.boss);
            assertTrue(r.evidenceOnly);
            assertFalse(EncounterReportCodec.encodeObservation(r).has("creditEventId"));
            assertNull(r.signals.get(1).previous);
            assertEquals("server_observation", EncounterReportCodec.encodeObservation(r).get("trackingMode").getAsString());
        }
        c.counter("Your Dagannoth Rex kill count is: 51.", "Example", id, 120, 13000);
        c.advance(130);
        assertEquals(Integer.valueOf(50), reports.get(3).signals.get(0).previous);
        c.interrupt(131, EncounterObservation.Reason.LOGOUT);
        c.counter("Your Dagannoth Rex kill count is: 52.", "Example", id, 140, 25000);
        c.advance(150);
        assertNull(reports.get(4).signals.get(0).previous);
        assertFalse(c.counter("Your Dagannoth Kings kill count is: 820.", "Example", id, 151, 26000));
        assertFalse(c.npc("Spinolyp", false, "Example", id, 151, 26000));
    }
    @Test public void assignmentChangeDoesNotReuseCounterOrOtherKingSignals()
    {
        List<EncounterObservation.Snapshot> reports = new ArrayList<>();
        DagannothComponentCollector c = new DagannothComponentCollector(reports::add);
        String old = UUID.randomUUID().toString(), next = UUID.randomUUID().toString();
        c.counter("Your Dagannoth Rex kill count is: 50.", "Example", old, 100, 1000);
        c.npc("Dagannoth Prime", false, "Example", old, 101, 1600);
        c.counter("Your Dagannoth Rex kill count is: 51.", "Example", next, 102, 2200);
        c.advance(112);
        EncounterObservation.Snapshot latest = reports.get(reports.size() - 1);
        assertEquals(UUID.fromString(next), latest.assignmentId);
        assertEquals(1, latest.signals.size());
        assertNull(latest.signals.get(0).previous);
    }
}

package com.huntmaster;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class DoomCompletionEvidenceTest
{
    private final List<EncounterObservation.Snapshot> reports = new ArrayList<>();
    private final EncounterCapture capture = new EncounterCapture(reports::add);
    private final BossDetector doom = new BossDetector(BossDefinition.totalCounterCandidate(DoomCompletionEvidence.BOSS, "doom"));
    private final String assignment = UUID.randomUUID().toString();
    private static String message(int level)
    {
        return "Delve level: " + (level > 8 ? "8+ (" + level + ")" : level) + " duration: 1:02.40";
    }
    private void complete(int level, int tick)
    {
        capture.doomCompletion(doom, "Example", assignment, tick, 100000L + tick * 600,
            DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, message(level)));
    }
    private void counter(Integer before, int after, int tick)
    {
        capture.counter(doom, "Example", assignment, tick, 100000L + tick * 600,
            EncounterObservation.CounterSource.COMPLETION_VARP, before, after);
    }
    private JsonObject report(int i) { return EncounterReportCodec.encodeObservation(reports.get(i)); }

    @Test public void parsesAllLevelsAndKnownDurationForms()
    {
        for (int level : new int[]{1, 7, 8, 9, 10, 100, Integer.MAX_VALUE})
        {
            DoomCompletionEvidence e = DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, message(level));
            assertNotNull(e); assertEquals(level, e.completedLevel); assertEquals(level > 8, e.extended);
        }
        assertNotNull(DoomCompletionEvidence.parse(ChatMessageType.SPAM,
            "Delve level: <col=ff0000>8</col> duration: <col=ff0000>1:02.40</col>. Personal best: 0:59.40."));
        assertNotNull(DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, message(8) + " (new personal best)"));
    }

    @Test public void rejectsPlayerChatMalformedAndOtherMessages()
    {
        for (ChatMessageType type : ChatMessageType.values())
            if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
                assertNull(DoomCompletionEvidence.parse(type, message(8)));
        for (String value : new String[]{"", "Delve level: 8 duration:", "Delve level: 8 duration: 1:99",
            message(0), "Delve level: 9 duration: 1:02.40", "Delve level: 8+ (8) duration: 1:02.40",
            "Delve level: 8+ (2147483648) duration: 1:02.40", "Delve level 1 - 8 duration: 10:02.40",
            "Your Doom of Mokhaiotl kill count is: 8.", "Entering delve level 8", "You have died.",
            "Player: " + message(8), message(8) + " arbitrary trailing text", "x".repeat(513)})
            assertNull(value, DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, value));
        assertNull(DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, null));
    }

    @Test public void levelsEightNineTenRemainSeparateEvenWithinOneWindow()
    {
        for (int i = 0; i < 3; i++) { complete(8 + i, 10 + 2 * i); counter(100 + i, 101 + i, 11 + 2 * i); }
        capture.advance(30);
        assertEquals(3, reports.size());
        for (int i = 0; i < 3; i++)
        {
            assertEquals(8 + i, reports.get(i).doomState.completedLevel);
            assertEquals(2, reports.get(i).signals.size());
            assertEquals(Integer.valueOf(101 + i), reports.get(i).signals.get(1).current);
            if (i > 0) assertNotEquals(reports.get(i-1).reportId, reports.get(i).reportId);
        }
    }

    @Test public void counterMayArriveBeforeOrAfterMessage()
    {
        counter(5, 6, 10); complete(8, 12); capture.advance(20);
        assertEquals(1, reports.size()); assertEquals(2, reports.get(0).doomState.tickOffset);
        complete(9, 30); counter(6, 7, 39); capture.advance(40);
        assertEquals(2, reports.size()); assertEquals(9, reports.get(1).signals.get(1).tickOffset);
    }

    @Test public void lowerLevelAndMissingCounterRemainTruthfulObservations()
    {
        complete(7, 10); capture.advance(20);
        assertEquals(7, report(0).getAsJsonObject("doomState").get("completedLevel").getAsInt());
        assertEquals(1, reports.get(0).signals.size());
        assertEquals("unresolved", report(0).get("outcome").getAsString());
        assertFalse(report(0).has("verificationMethod"));
    }

    @Test public void initialSynchronizationAndCounterOnlyNeverClaimCompletion()
    {
        counter(null, 100, 10); counter(100, 100, 11); capture.advance(30); assertTrue(reports.isEmpty());
        counter(100, 101, 40); capture.advance(50);
        assertNull(reports.get(0).doomState); assertEquals(1, reports.get(0).signals.size());
        assertEquals(EncounterObservation.SignalKind.COUNTER, reports.get(0).signals.get(0).kind);
    }

    @Test public void expiryAndAmbiguityDoNotInventPairings()
    {
        complete(8, 10); counter(5, 6, 20); capture.advance(30);
        assertEquals(2, reports.size()); assertEquals(1, reports.get(0).signals.size()); assertNull(reports.get(1).doomState);
        complete(9, 40); complete(10, 41); counter(6, 7, 42); capture.advance(60);
        assertEquals(5, reports.size());
        for (int i = 2; i < 5; i++) assertEquals(1, reports.get(i).signals.size());
    }

    @Test public void jumpsAndDecreasesRemainRawEvidence()
    {
        complete(8, 10); counter(5, 10, 11); capture.advance(20);
        assertEquals(Integer.valueOf(5), reports.get(0).signals.get(1).previous);
        assertEquals(Integer.valueOf(10), reports.get(0).signals.get(1).current);
        assertEquals("unresolved", report(0).get("outcome").getAsString());
    }

    @Test public void interruptionAndReloadDoNotCarryEvidenceIntoNextEncounter()
    {
        complete(8, 10); counter(5, 6, 11); capture.advance(20);
        capture.interrupt(21, EncounterObservation.Reason.LOGOUT);
        assertTrue(reports.get(0).captureComplete);
        complete(9, 30); capture.interrupt(31, EncounterObservation.Reason.SHUTDOWN); capture.clear();
        assertFalse(reports.get(1).captureComplete);
        counter(null, 100, 1); counter(100, 101, 2); capture.advance(12);
        assertNull(reports.get(2).doomState);
    }

    @Test public void accountAndAssignmentChangesCannotPair()
    {
        counter(5, 6, 10);
        capture.doomCompletion(doom, "Other", null, 11, 106600,
            DoomCompletionEvidence.parse(ChatMessageType.GAMEMESSAGE, message(8)));
        capture.advance(30);
        assertEquals(2, reports.size()); assertFalse(reports.get(0).captureComplete);
        assertEquals(1, reports.get(1).signals.size()); assertNull(reports.get(1).assignmentId);
    }

    @Test public void duplicateNotificationAndRetryKeepIdentityAndPayload()
    {
        complete(8, 10); complete(8, 10); counter(5, 6, 11); capture.advance(20);
        assertEquals(1, reports.size());
        String payload = report(0).toString(), id = reports.get(0).reportId.toString();
        EncounterReportQueue q = new EncounterReportQueue(); assertTrue(q.add(id, payload, 1000, 1000, true));
        assertFalse(q.add(id, payload, 1000, 1000, true));
        EncounterReportQueue.Entry entry = q.next(1000); entry.inFlight = true; q.releaseInFlight();
        assertSame(entry, q.next(1001));
        EncounterReportQueue.Entry restored = new Gson().fromJson(new Gson().toJson(entry), EncounterReportQueue.Entry.class);
        EncounterReportQueue next = new EncounterReportQueue(); next.add(restored.id, restored.payload, restored.createdAt, 1001, true);
        assertEquals(id, next.next(1001).id); assertEquals(payload, next.next(1001).payload);
        assertTrue(payload.length() < 8192); assertFalse(payload.contains("duration:"));
        assertEquals("/api/runelite/observations", EncounterReportCodec.deliveryRoute(report(0)));
    }

    @Test public void pendingRecordsRemainBoundedAndNonDoomSchemaUnchanged()
    {
        for (int i = 1; i <= 20; i++) complete(8 + i, 10);
        capture.advance(20); assertEquals(20, reports.size());
        assertEquals(12, reports.stream().filter(s -> !s.captureComplete).count());
        BossDetector other = new BossDetector(BossDefinition.totalCounterCandidate("Royal Titans", "titans"));
        capture.primary(other, "Example", null, 40, 124000, EncounterObservation.SignalKind.COMPLETION);
        capture.counter(other, "Example", null, 41, 124600, EncounterObservation.CounterSource.COMPLETION_VARP, 10, 11);
        capture.advance(50);
        JsonObject result = report(20); assertFalse(result.has("doomState"));
        assertEquals(1, result.get("schemaVersion").getAsInt()); assertEquals(2, result.getAsJsonArray("signals").size());
    }
}

